content.a:expression:
a!formLayout(
  label: "HR Management - Employee Onboarding & Bonus Review",
  instructions: "Review employee background and performance metrics to approve or reject request.",
  contents: {
    a!readOnlyGridField(
      label: "Employee Profile",
      data: ri!employee,
      columns: {
        a!gridColumn(label: "Employee Name", value: concat(fv!row.firstName, " ", fv!row.lastName)),
        a!gridColumn(label: "Department", value: fv!row.department),
        a!gridColumn(label: "Base Salary ($)", value: fv!row.salary),
        a!gridColumn(label: "Status", value: fv!row.status)
      }
    ),
    a!sectionLayout(
      label: "Approval Decision",
      contents: {
        a!radioButtonField(
          label: "Decision",
          choiceLabels: {"Approve Employee", "Reject Request"},
          choiceValues: {"APPROVED", "REJECTED"},
          value: ri!employee.status,
          saveInto: ri!employee.status,
          required: true()
        ),
        a!paragraphField(
          label: "HR Rationale Notes",
          placeholder: "Enter manager justification...",
          value: ri!notes,
          saveInto: ri!notes,
          required: true()
        )
      }
    )
  },
  buttons: a!buttonLayout(
    primaryButtons: {
      a!buttonWidget(
        label: "Submit Verdict",
        submit: true(),
        style: "PRIMARY"
      )
    }
  )
)
